//! Independent synthetic dictionaries generated by graph/tests/make_fixture.py.
//! These fixtures contain invented examples, no unprocessed source data.
use ipa_graph::{CandidateKind, Engine, QueryOptions, QueryStatus};
use std::sync::atomic::{AtomicU64, Ordering};
static NEXT: AtomicU64 = AtomicU64::new(0);

struct Fixture(std::path::PathBuf);
impl Fixture {
    fn new(bytes: &[u8]) -> Self {
        let path = std::env::temp_dir().join(format!(
            "ipa-rust-core-{}-{}.ipad",
            std::process::id(),
            NEXT.fetch_add(1, Ordering::Relaxed)
        ));
        std::fs::write(&path, bytes).unwrap();
        Self(path)
    }
    fn engine(&self) -> Engine {
        // SAFETY: each fixture owns a unique immutable file until engine drop.
        unsafe { Engine::load(&self.0).unwrap() }
    }
}
impl Drop for Fixture {
    fn drop(&mut self) {
        let _ = std::fs::remove_file(&self.0);
    }
}
fn strict() -> QueryOptions {
    QueryOptions {
        allow_omissions: false,
        ..QueryOptions::default()
    }
}

#[test]
fn formats_exact_prefix_front_coding_and_policies() {
    for (bits, bytes) in [
        (24, include_bytes!("fixtures/synthetic-24.ipad").as_slice()),
        (32, include_bytes!("fixtures/synthetic-32.ipad").as_slice()),
    ] {
        let file = Fixture::new(bytes);
        let engine = file.engine();
        assert_eq!(engine.key_count(), 33);
        assert_eq!(engine.word_count(), 32);
        assert_eq!(engine.index_bits(), bits);
        assert_eq!(engine.arc_record_bytes(), bits / 8 + 1);
        let exact = engine.query("a", strict());
        assert_eq!(exact.status, QueryStatus::Ok);
        assert!(exact.exact_found);
        assert_eq!(exact.candidates.len(), 2);
        assert_eq!(exact.matched_records, 3);
        assert_eq!(exact.candidates[0].text, "alpha");
        assert_eq!(exact.candidates[0].language, "EN");
        assert_eq!(engine.query("ba", strict()).candidates[0].text, "alpha");
        assert_eq!(engine.query("ɕoː", strict()).candidates[0].text, "学校");
        assert_eq!(
            engine.query("ni˨˩˦", strict()).candidates[0].language,
            "简/繁"
        );
        let mut options = strict();
        options.candidate_limit = 1;
        let one = engine.query("cb", options);
        assert_eq!(one.candidates[0].text, "爱");
        assert_eq!(one.candidates[0].language, "简/繁");
        let mut options = strict();
        options.prefix = true;
        let prefix = engine.query("a", options);
        assert_eq!(prefix.candidates.len(), 4);
        assert_eq!(prefix.matched_keys, 3);
        assert_eq!(prefix.candidates[2].kind, CandidateKind::Completion);
        options.prefix_key_budget = 1;
        let prefix = engine.query("a", options);
        assert!(prefix.truncated);
        assert_eq!(prefix.matched_keys, 1);
        options.prefix_key_budget = 65536;
        options.candidate_limit = 180;
        let prefix = engine.query("x", options);
        assert_eq!(prefix.candidates.len(), 26);
        assert_eq!(prefix.candidates[0].text, "word-25");
        assert_eq!(prefix.candidates.last().unwrap().text, "word-00");
        engine.configure(4);
        assert_eq!(engine.query("a", strict()).candidates[0].text, "啊");
        engine.configure(0);
        assert!(engine.query("a", strict()).candidates.is_empty());
        assert!(!engine.accepts_input(""));
        assert!(!engine.accepts_input(&"a".repeat(65)));
        assert!(!engine.accepts_input("a🙂"));
        assert_eq!(
            engine.query("a🙂", strict()).status,
            QueryStatus::UnsupportedInput
        );
    }
}

#[test]
fn ordered_omissions_numeric_tones_unicode_and_limits() {
    let file = Fixture::new(include_bytes!("fixtures/omissions.ipad"));
    let engine = file.engine();
    let options = QueryOptions {
        candidate_limit: 180,
        ..QueryOptions::default()
    };
    for (raw, word) in [
        ("maɪ", "my"),
        ("nixɑʊ", "你好"),
        ("ni35 xɑʊ̯21", "你好"),
        ("ni35xɑʊ21", "你好"),
        ("ɕoɡa", "fixture-japanese"),
        ("e", "accent-e"),
    ] {
        let result = engine.query(raw, options);
        assert_eq!(result.status, QueryStatus::Ok, "{raw}");
        assert!(
            result.candidates.iter().any(|c| c.text == word),
            "{raw}: {result:?}"
        );
    }
    for raw in ["é", "e\u{301}", "ni35 xɑʊ̯21"] {
        let result = engine.query(raw, options);
        assert!(result.exact_found);
        assert_eq!(result.candidates[0].omitted_symbols, 0);
    }
    for raw in ["ni0", "ni6", "ni３"] {
        assert_eq!(
            engine.query(raw, options).status,
            QueryStatus::UnsupportedInput
        );
    }
    for (raw, word) in [
        ("ɪam", "my"),
        ("maɪa", "my"),
        ("xɑʊni", "你好"),
        ("ni53 xɑʊ̯21", "你好"),
    ] {
        assert!(
            !engine
                .query(raw, options)
                .candidates
                .iter()
                .any(|c| c.text == word),
            "{raw}"
        );
    }
    assert!(engine.query("maɪ", strict()).candidates.is_empty());
    let exact = engine.query(
        "a",
        QueryOptions {
            omission_state_budget: 1,
            ..options
        },
    );
    assert!(exact.exact_found);
    assert!(exact.truncated);
    assert!(exact.explored_states <= 1);
    assert_eq!(exact.candidates[0].text, "exact-a");
    let prefix = engine.query(
        "a",
        QueryOptions {
            prefix: true,
            prefix_key_budget: 1,
            ..options
        },
    );
    assert!(prefix.truncated);
    assert!(!prefix
        .candidates
        .iter()
        .any(|c| c.kind == CandidateKind::Completion));
    assert!(prefix.candidates.iter().any(|c| c.text == "long-bab"));
}

#[test]
fn rejects_corrupt_headers_arcs_postings_words_and_truncation() {
    let original = include_bytes!("fixtures/synthetic-24.ipad");
    let offset = |i: usize| {
        u64::from_le_bytes(original[36 + i * 8..44 + i * 8].try_into().unwrap()) as usize
    };
    for (at, value) in [
        (0, b'X'),
        (8, 99),
        (36, 0),
        (offset(3), 0),
        (offset(5), 0),
        (offset(7), 1),
    ] {
        let mut bytes = original.to_vec();
        bytes[at] = value;
        let file = Fixture::new(&bytes);
        // SAFETY: this unique fixture is immutable during the attempted load.
        assert!(unsafe { Engine::load(&file.0) }.is_err(), "offset {at}");
    }
    for length in [0, 107, original.len() - 1] {
        let file = Fixture::new(&original[..length]);
        // SAFETY: this unique fixture is immutable during the attempted load.
        assert!(unsafe { Engine::load(&file.0) }.is_err());
    }
}

#[test]
fn concurrent_queries_share_graph_and_snapshot_policy() {
    let file = Fixture::new(include_bytes!("fixtures/synthetic-24.ipad"));
    let engine = file.engine();
    let workers: Vec<_> = (0..4)
        .map(|_| {
            let engine = engine.clone();
            std::thread::spawn(move || {
                for _ in 0..1000 {
                    let result = engine.query("a", strict());
                    assert_eq!(result.status, QueryStatus::Ok);
                    assert!(result.candidates.len() <= 2);
                    assert!(result
                        .candidates
                        .iter()
                        .all(|c| c.rank >= 0 && c.context_affinity.is_finite()));
                }
            })
        })
        .collect();
    for i in 0..1000 {
        engine.configure(if i % 2 == 0 { 5 } else { 4 });
    }
    for worker in workers {
        worker.join().unwrap();
    }
}
